import time

class SimpleCache:
    def __init__(self):
        self._store = {}

    def get(self, key):
        if key not in self._store:
            return None
        value, expires_at = self._store[key]
        if expires_at and time.time() >= expires_at:
            del self._store[key]
            return None
        return value

    def set(self, key, value, ttl=None):
        expires_at = time.time() + ttl if ttl else None
        self._store[key] = (value, expires_at)

