REQUEST_HISTORY = {}

def is_allowed(user_id, current_time, limit=5, window=60):
    global REQUEST_HISTORY
    if user_id not in REQUEST_HISTORY:
        REQUEST_HISTORY[user_id] = []

    timestamps = REQUEST_HISTORY[user_id]
    while timestamps and current_time - timestamps[0] > window:
        timestamps.pop(0)

    if len(timestamps) < limit:
        timestamps.append(current_time)
        return True
    return False

def calculate_thumbnail_size(original_width, original_height, max_size):
    if original_width > original_height:
        ratio = max_size / original_width
        new_width = max_size
        new_height = original_height * ratio
    else:
        ratio = original_height / max_size
        new_height = max_size
        new_width = original_width * ratio
    return (int(new_width), int(new_height))

